from pathlib import Path
from datetime import datetime, timezone
import base64,hashlib,json,os,tempfile
ROOT=Path('/var/www/business.roadrunners.run')
os.umask(0o077)
PAYLOAD = {'includes/backend/cron_jobs_service.cfm': '', 'administracao/cron-jobs/includes/backend.cfm': '', 'administracao/cron-jobs/home.cfm': '', 'cron-jobs/runner.cfm': ''}
MANIFEST = {'includes/backend/cron_jobs_service.cfm': {'before': 'cfb9f9eec5fe7272e3dc07217c002dae5748c6e78b00532eec2c26e411b142d4', 'after': '2cdbbdcb5304ab274dfd0f8ac08656685bfe2516e708a9f0deedfcbd97b37270'}, 'administracao/cron-jobs/includes/backend.cfm': {'before': 'b22e437a86d58a40d7935041ee8a92c18abf16c1023b1df085a5d6c067b7f896', 'after': 'abdfeef2c1b2a5ae7d10963d04b001f6bcbf47dc152756ca77406b5bfbe8c4d3'}, 'administracao/cron-jobs/home.cfm': {'before': 'a8f13f9588d40566c7505dcf5f093722f06ba3fde454992a76d750d75064b29a', 'after': 'd9371c8561f2ff43b602f7b6f565212f0472de9ffc38509e9db9eaeed11f1384'}, 'cron-jobs/runner.cfm': {'before': 'a5bba9d1e900655865811480c5db6c419114c1aed002d67b269467b7e33c782d', 'after': '3fb19ec63c4aec38500dea20f58c5dab81c7a81a979651d58450eaac23464f1b'}}
sha=lambda data:hashlib.sha256(data).hexdigest()
order=['includes/backend/cron_jobs_service.cfm', 'administracao/cron-jobs/includes/backend.cfm', 'administracao/cron-jobs/home.cfm', 'cron-jobs/runner.cfm']
for name in order:
 if sha((ROOT/name).read_bytes())!=MANIFEST[name]['before']:raise RuntimeError('Production baseline conflict: '+name)
 if sha(base64.b64decode(PAYLOAD[name]))!=MANIFEST[name]['after']:raise RuntimeError('Candidate integrity mismatch: '+name)
backup=Path(tempfile.mkdtemp(prefix='business-cron-timezone-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-',dir='/var/backups'))
metadata={}
for name in order:
 path=ROOT/name;state=path.stat();metadata[name]={'uid':state.st_uid,'gid':state.st_gid,'mode':state.st_mode & 0o777}
 original=backup/'before'/name;original.parent.mkdir(parents=True,exist_ok=True);original.write_bytes(path.read_bytes())
(backup/'manifest.json').write_text(json.dumps({'hashes':MANIFEST,'metadata':metadata},indent=2)+'\n')
def install(name,data):
 target=ROOT/name
 fd,tmp=tempfile.mkstemp(prefix='.cron-timezone-fix-',dir=target.parent)
 try:
  with os.fdopen(fd,'wb') as out:out.write(data);out.flush();os.fsync(out.fileno())
  os.chown(tmp,metadata[name]['uid'],metadata[name]['gid']);os.chmod(tmp,metadata[name]['mode']);os.replace(tmp,target)
 finally:
  if Path(tmp).exists():Path(tmp).unlink()
changed=[]
try:
 for name in order:
  if sha((ROOT/name).read_bytes())!=MANIFEST[name]['before']:raise RuntimeError('Concurrent production change: '+name)
  install(name,base64.b64decode(PAYLOAD[name]));changed.append(name)
  if sha((ROOT/name).read_bytes())!=MANIFEST[name]['after']:raise RuntimeError('Publication hash mismatch: '+name)
except Exception:
 for name in reversed(changed):
  if sha((ROOT/name).read_bytes())==MANIFEST[name]['after']:install(name,(backup/'before'/name).read_bytes())
 raise
report={'backup':str(backup),'published_at_utc':datetime.now(timezone.utc).isoformat(),'files':MANIFEST,'metadata_preserved':True,'server_permissions_changed':False}
(backup/'result.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
